/* Heavy base64 font data — kept in its own module so the main
 * signature-fonts loader can dynamic-import() it and we don't ship
 * ~885KB of base64 in the initial JS bundle for the landing route. */

export type BundledFont = {
  family: string;
  url: string;
  format: "truetype" | "opentype";
};

const royaltyUrl = "data:font/ttf;base64,";
const testimoniaUrl = "data:font/ttf;base64,";
const paulSignatureUrl = "data:font/ttf;base64,";
const taylorSwiftUrl = "data:font/ttf;base64,";
const caramelliaUrl = "data:font/ttf;base64,";
const stayClassyUrl = "data:font/ttf;base64,";
const rondeRoyalUrl = "data:font/otf;base64,";
const rightmanUrl = "data:font/otf;base64,";
const dwayneDylanUrl = "data:font/otf;base64,";

export const bundledSignatureFonts: BundledFont[] = [
  { family: "Royalty Signature", url: royaltyUrl, format: "truetype" },
  { family: "Testimonia Signature", url: testimoniaUrl, format: "truetype" },
  { family: "Paul Signature", url: paulSignatureUrl, format: "truetype" },
  { family: "Taylor Swift", url: taylorSwiftUrl, format: "truetype" },
  { family: "Caramellia", url: caramelliaUrl, format: "truetype" },
  { family: "Stay Classy", url: stayClassyUrl, format: "truetype" },
  { family: "Ronde Royal", url: rondeRoyalUrl, format: "opentype" },
  { family: "Rightman Signature", url: rightmanUrl, format: "opentype" },
  { family: "Dwayne Dylan", url: dwayneDylanUrl, format: "opentype" },
];
